	// Used for StringUtils
	importPackage(org.apache.commons.lang3);

	// Defaults to standard HL7 encoding characters
	var fs = fieldSeparator || '|';
	var cs = componentSeparator || '^';
	var rm = repetitionMarker || '~';
	var ss = subcomponentSeparator || '&';
	var cr = '\x0D';

	// What will actually be returned
	var output = '';
	// Get the XML name of the node (in the case of an XMLList of repeating fields, the first one will be returned, since they all have the same name anyway)
	var qname = node[0].name().toString();
	// Use the HL7 dot notation to find what level we're at
	var level = StringUtils.countMatches(qname,'.');

	// If the name is HL7Message, we're at the root node
	if (qname == 'HL7Message') {
		// Recursively append serialization for each segment
		for each (segment in node.children()) {
			output += xmlToHL7(segment,fs,cs,rm,ss);
		}
	} else if (level == 0) { // If we're at the segment level
		// If the node is an XMLList of multiple segments
		if (node.length() > 1) {
			// Recursively append serialization for each segment
			for each (segment in node) {
				output += xmlToHL7(segment,fs,cs,rm,ss);
			}
		} else {
			// Add the segment name to the output
			output += qname;
			// Initialize name placeholder
			var prevName = '';

			// Iterate through each field in the segment
			for each (field in node.children()) {
				// Get the QName of the field
				var fieldName = field.name().toString();

				// If we're dealing with the special cases of MSH.1/2, then just add the field contents
				if (fieldName in {'MSH.1':1,'MSH.2':1}) {
					output += field.toString().replaceAmp();
				} else { // Otherwise add the recursive serialization of the field
					// If we're on a field repetition, then prepend a repetition marker, otherwise prepend a field separator
					output += (prevName==fieldName?rm:fs) + xmlToHL7(field,fs,cs,rm,ss);
				}

				// Update the field name placeholder
				prevName = fieldName;
			}

			// Add a carriage return to the end of the segment
			output += cr;
		}
	} else if (level == 1) { // If we're at the field level
		// If the node is an XMLList of multiple fields
		if (node.length() > 1) {
			// Recursively append serialization for each field
			for each (field in node) {
				output += xmlToHL7(field,fs,cs,rm,ss) + rm;
			}

			// Remove the final repetition marker
			output = StringUtils.chomp(output,rm);
		}
		else {
			// Recursively append serialization for each component
			for each (component in node.children()) {
				// Append a component separator to the end
				output += xmlToHL7(component,fs,cs,rm,ss) + cs;
			}

			// Remove the last component separator
			output = StringUtils.chomp(output,cs);
		}
	} else if (level == 2) { // If we're at the component level
		// Recursively append serialization for each subcomponent
		for each (subcomponent in node.children()) {
			// Append a subcomponent separator to the end
			output += xmlToHL7(subcomponent,fs,cs,rm,ss) + ss;
		}

		// Remove the last subcomponent separator
		output = StringUtils.chomp(output,ss);
	} else { // If we're at the subcomponent level
		// Just add the contents of the node
		output = node.toString().replaceAmp();
	}

	// Return the final output
	return output;
}

/**
    For a given key, retrieve the value from the globalMap. If the globalMap does not contain the key or
    the object returned is null produce and store a new object in a thread-safe manner.

    @param {string} globalMapKey - Key under which this object is stored in the globalMap. Also used
        as the key for the synchronization object in the globalMap.
    @param {function():any} initializer - Function which will be called when the value for
        globalMapKey is null. Returns the object to be stored as the value for globalMapKey.
    @return {any} Object previously stored by globalMapKey or object created by initializer.

    @author Tony Germano
*/
function getInstance(globalMapKey, initializer) {
    var val = globalMap.get(globalMapKey);
    if (val == null)  {
        if (!globalMap.containsKeySync(globalMapKey)) {
            globalMap.putSync(globalMapKey,null);
        }
        try {
            globalMap.lock(globalMapKey);
            if ((val = globalMap.get(globalMapKey)) == null) {
                val = initializer();
                globalMap.put(globalMapKey, val);
            }
        }
        finally {
            globalMap.unlock(globalMapKey);
        }
    }
    return val;
};

importPackage(javax.xml);
importPackage(javax.xml.transform.stream);
importPackage(javax.xml.validation);

// Create thread-safe Schema once and store in global channel map
var schema = $gc('schema');
if (schema == null) {
	var schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
	var xsd = new java.net.URL('http://www.hl7.org/fhir/patient.xsd');
	schema = schemaFactory.newSchema(xsd);
	$gc('schema', schema);
}

var errors = Lists.list();
var fatalErrors = Lists.list();
var warnings = Lists.list();
var handler = new JavaAdapter(org.xml.sax.ErrorHandler, {
	error: function(e) {
		errors.add(e);
	},
	fatalError: function (e) {
		fatalErrors.add(e);
	},
	warning: function (e) {
		warnings.add(e);
	}
});

var validator = schema.newValidator();
validator.setErrorHandler(handler);
var source = new StreamSource(new java.io.StringReader(msg));

try {
	validator.validate(source);
} catch (e) {
	if (e.javaException) {
		errors.add(e.javaException);
	} else {
		errors.add(e);
	}
}

if (!warnings.isEmpty()) {
	var builder = new java.lang.StringBuilder();
	builder.append(new java.lang.Integer(warnings.size()).toString()).append(' warnings while validating XML.');

	processErrors(warnings, builder, 'Warning');

	$r('validationWarnings', new Response(Status.ERROR, '', builder.toString()));
}

if (!errors.isEmpty() || !fatalErrors.isEmpty()) {
	var builder = new java.lang.StringBuilder('Error validating XML: ');
	builder.append(new java.lang.Integer(errors.size()).toString()).append(' errors and ').append(new java.lang.Integer(fatalErrors.size()).toString()).append(' fatal errors.');

	processErrors(errors, builder, 'Error');
	processErrors(fatalErrors, builder, 'FATAL Error');

	$r('validationErrors', new Response(Status.ERROR, '', builder.toString()));
	return false;
}

return true;

function processErrors(list, builder, prefix) {
	for (var i = 0; i < list.size(); i++) {
		builder.append('\n\n').append(prefix).append(' #').append(new java.lang.Integer(i+1).toString()).append(': ');

		var e = list.get(i);
		if (e instanceof java.lang.Exception) {
			builder.append(org.apache.commons.lang3.exception.ExceptionUtils.getStackTrace(e));
		} else {
			builder.append(e.toString());
		}
	}
}

